python3 -c 'from docx import Document; from openpyxl import load_workbook; import json, pathlib; base=pathlib.Path("/documents");
for f in ["客户情况与委托说明.docx","沟通情况整理.docx"]:
 d=Document(base/f); print("\\n###",f); 
 for p in d.paragraphs:
  if p.text.strip(): print(p.text)
 for ti,t in enumerate(d.tables):
  print("[TABLE",ti,"]");
  for r in t.rows: print(" | ".join(c.text.replace("\\n"," / ") for c in r.cells))
w=load_workbook(base/"付款退款明细.xlsx",data_only=False); print("\\n### 付款退款明细.xlsx");
for s in w:
 print("[SHEET",s.title,s.max_row,s.max_column,"]");
 for r in s.iter_rows(values_only=True): print(json.dumps(r,ensure_ascii=False,default=str))'

