  want="SimHei" if heading else "FangSong"
  for r in par.runs:
    if not r.text: continue
    rp=r._element.rPr; rf=rp.rFonts if rp is not None else None
    vals=[rf.get(qn("w:"+a)) if rf is not None else None for a in ("ascii","hAnsi","eastAsia","cs")]
    if vals != [want]*4: errs.append((par.text[:25],r.text[:25],want,vals))
for n in ("Title","Heading 1","Heading 2","Heading 3"):
